//! Drives the `kpf` binary offline through a scripted lifecycle against an in-memory UTXO set, with the script engine
//! (`kpf_protocol::sim::Chain`) as the chain: two orders -> open -> list -> transfer -> add margin -> mutual close ->
//! cooperative close -> idle settle, then cancel, refund, open-taker and close-versus-close.
//!
//! No node is contacted and nothing is submitted. Keys are generated by `kpf keygen` into a temporary directory
//! outside any repository.

use std::path::{Path, PathBuf};
use std::process::Command;

use kaspa_consensus_core::tx::TransactionOutpoint;
use kpf_protocol::sim::Chain;
use kpf_protocol::state::{decode_redeem, Decoded};
use kpf_protocol::tx::{tx_from_rpc_json, Obj};
use serde_json::{json, Value};

const KAS: u64 = 100_000_000;

struct H {
    dir: PathBuf,
    chain: Chain,
    steps: usize,
}

impl Drop for H {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.dir);
    }
}

fn bin() -> Command {
    Command::new(env!("CARGO_BIN_EXE_kpf"))
}

impl H {
    fn new(tag: &str) -> H {
        let dir = std::env::temp_dir().join(format!("kpf-cli-{tag}-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let mut chain = Chain::new();
        chain.advance(1_000);
        H { dir, chain, steps: 0 }
    }

    fn p(&self, name: &str) -> String {
        self.dir.join(name).display().to_string()
    }

    fn run(&self, args: &[&str]) -> (bool, String, String) {
        let o = bin().args(args).output().expect("run kpf");
        (o.status.success(), String::from_utf8_lossy(&o.stdout).into_owned(), String::from_utf8_lossy(&o.stderr).into_owned())
    }

    fn ok(&self, args: &[&str]) -> String {
        let (ok, out, err) = self.run(args);
        assert!(ok, "kpf {args:?} failed:\n{err}\n{out}");
        out
    }

    fn fail(&self, args: &[&str]) -> String {
        let (ok, out, err) = self.run(args);
        assert!(!ok, "kpf {args:?} should have failed:\n{out}");
        err
    }

    /// A key file by `kpf keygen`; returns (path, x-only public key).
    fn key(&self, name: &str) -> (String, [u8; 32]) {
        let path = self.p(&format!("{name}.key.json"));
        self.ok(&["keygen", "--out", &path]);
        let v: Value = serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap();
        (path, hex32(v["publicKey"].as_str().unwrap()))
    }

    /// The funding file of `key`: its current plain UTXOs on the chain.
    fn funding(&self, name: &str, key: &[u8; 32]) -> String {
        let mut utxos = self.chain.key_utxos(key);
        utxos.sort_by_key(|u| std::cmp::Reverse(u.amount));
        utxos.truncate(1); // a funding file is used exactly as listed: give the largest UTXO only
        let list: Vec<Value> = utxos
            .iter()
            .map(|u| json!({"txid": u.outpoint.transaction_id.to_string(), "index": u.outpoint.index, "amount": u.amount, "daa": u.daa}))
            .collect();
        let path = self.p(&format!("funding-{name}.json"));
        std::fs::write(&path, serde_json::to_string(&list).unwrap()).unwrap();
        path
    }

    /// Runs a builder command (adding `--out-dir`, `--brief`), applies its transaction to the chain, and returns the
    /// object files it created in output order.
    fn step(&mut self, args: &[&str]) -> Vec<String> {
        self.steps += 1;
        let out = self.p(&format!("out{}", self.steps));
        let mut a: Vec<&str> = args.to_vec();
        a.extend(["--out-dir", &out, "--brief"]);
        let stdout = self.ok(&a);
        assert!(stdout.contains("verification: every one of"), "{stdout}");
        assert!(stdout.contains("not submitted"), "{stdout}");
        assert!(stdout.contains("who pays and receives"), "{stdout}");
        let txfile = std::fs::read_dir(&out).unwrap().map(|e| e.unwrap().path()).find(|p| p.to_string_lossy().ends_with("-tx.json")).expect("tx file");
        let doc: Value = serde_json::from_str(&std::fs::read_to_string(&txfile).unwrap()).unwrap();
        assert_eq!(doc["verification"]["ok"], true);
        println!(
            "STEP {:<14} fee {:>9} sompi  compute mass {:>6}  storage mass {:>6}  units {:?}",
            args[0],
            doc["fee"],
            doc["mass"]["compute"],
            doc["mass"]["storage"],
            doc["verification"]["inputs"].as_array().unwrap().iter().map(|i| i["scriptUnits"].as_u64().unwrap_or(0)).collect::<Vec<_>>()
        );
        let tx = tx_from_rpc_json(&doc["rpc"]).unwrap();
        assert_eq!(doc["txid"].as_str().unwrap(), tx.id().to_string());
        let files: Vec<String> = doc["created"].as_array().unwrap().iter().map(|v| v.as_str().unwrap().to_string()).collect();
        let mut created = vec![];
        for f in &files {
            let o: Value = serde_json::from_str(&std::fs::read_to_string(f).unwrap()).unwrap();
            let redeem = from_hex(o["redeem"].as_str().unwrap());
            let idx = o["outpoint"]["index"].as_u64().unwrap() as usize;
            created.push((
                idx,
                match decode_redeem(&redeem).unwrap() {
                    Decoded::Pair(p) => Obj::Pair(p),
                    Decoded::Open(o) => Obj::Open(o),
                },
            ));
        }
        // The chain re-runs every input in the engine on its own.
        self.chain.apply(&tx, &created).unwrap_or_else(|e| panic!("the chain refused {args:?}: {e}"));
        for f in &files {
            let mut o: Value = serde_json::from_str(&std::fs::read_to_string(f).unwrap()).unwrap();
            o["daa"] = json!(self.chain.daa);
            std::fs::write(f, serde_json::to_string_pretty(&o).unwrap()).unwrap();
        }
        files
    }
}

fn from_hex(s: &str) -> Vec<u8> {
    kpf_protocol::error::from_hex(s).unwrap()
}

fn hex32(s: &str) -> [u8; 32] {
    kpf_protocol::error::hex32(s).unwrap()
}

fn market_file(h: &H) -> String {
    let (ok, out, _) = h.run(&["market"]);
    assert!(ok);
    let path = h.p("market.json");
    std::fs::write(&path, out).unwrap();
    h.ok(&["market", "--check", &path]);
    path
}

fn object_kind(f: &str) -> String {
    let v: Value = serde_json::from_str(&std::fs::read_to_string(f).unwrap()).unwrap();
    v["kind"].as_str().unwrap().to_string()
}

fn object_size(f: &str) -> i64 {
    let v: Value = serde_json::from_str(&std::fs::read_to_string(f).unwrap()).unwrap();
    v["state"]["size"].as_i64().unwrap_or(-1)
}

#[test]
fn scripted_lifecycle() {
    let mut h = H::new("life");
    let market = market_file(&h);
    let (lk, l) = h.key("long");
    let (sk, s) = h.key("short");
    let (fk, f) = h.key("funder");
    let (ok_, o) = h.key("other");
    for _ in 0..20 {
        h.chain.mint(&f, 3_000 * KAS);
    }
    let _ = (ok_.clone(), o);

    // Two orders.
    let fund = h.funding("f", &f);
    let lo = h.step(&[
        "create-order", "--market", &market, "--side", "long", "--size", "2000", "--limit", "10.5", "--rate", "1", "--min-counter-rate", "1.5",
        "--min-fill", "100", "--tip", "0.01", "--expiry", "1000000000", "--owner", &lk, "--funder", &fk, "--funding", &fund,
    ]);
    assert_eq!(object_kind(&lo[0]), "order");
    let fund = h.funding("f", &f);
    let so = h.step(&[
        "create-order", "--market", &market, "--side", "short", "--size", "1000", "--limit", "9.5", "--rate", "2", "--min-counter-rate", "0.5",
        "--min-fill", "100", "--tip", "0.01", "--expiry", "1000000000", "--owner", &sk, "--funder", &fk, "--funding", &fund,
    ]);
    // Open 1,000 tokens at 10 KAS.
    let fund = h.funding("f", &f);
    let opened = h.step(&["open", "--long", &lo[0], "--short", &so[0], "--n", "1000", "--x", "10", "--funder", &fk, "--funding", &fund]);
    let pair = opened.iter().find(|p| object_kind(p) == "pair").cloned().expect("pair");
    assert_eq!(object_size(&pair), 1_000_000_000);
    // Inspect and quote the new pair offline.
    let ins = h.ok(&["inspect", &pair]);
    assert!(ins.contains("pair") && ins.contains("kaspatest:"), "{ins}");
    let q = h.ok(&["quote", "--pair", &pair, "--prices", "8.5,9,10,12,13"]);
    assert!(q.contains("1000") && q.contains("2000") && q.contains("3000"), "{q}");
    // List both sides.
    let fund = h.funding("f", &f);
    let p1 = h.step(&["amend", "--pair", &pair, "--side", "long", "--price", "10", "--key", &lk, "--funder", &fk, "--funding", &fund]);
    let fund = h.funding("f", &f);
    let p2 = h.step(&["amend", "--pair", &p1[0], "--side", "short", "--price", "10.5", "--min-part", "100", "--key", &sk, "--funder", &fk, "--funding", &fund]);
    // A new short order (rate 2.2) takes 400 tokens of the short's listing at 10.2.
    let fund = h.funding("f", &f);
    let so2 = h.step(&[
        "create-order", "--market", &market, "--side", "short", "--size", "1000", "--limit", "9", "--rate", "2.2", "--min-counter-rate", "0.5",
        "--min-fill", "100", "--tip", "0.01", "--expiry", "1000000000", "--owner", &ok_, "--funder", &fk, "--funding", &fund,
    ]);
    let fund = h.funding("f", &f);
    let moved = h.step(&[
        "transfer", "--pair", &p2[0], "--side", "short", "--n", "400", "--x", "10.2", "--entrant-order", &so2[0], "--funder", &fk, "--funding", &fund,
    ]);
    let part = moved.iter().find(|p| object_kind(p) == "pair" && object_size(p) == 400_000_000).cloned().expect("part");
    let rest = moved.iter().find(|p| object_kind(p) == "pair" && object_size(p) == 600_000_000).cloned().expect("rest");
    // The long adds margin to the remainder.
    let fund = h.funding("f", &f);
    let rest2 = h.step(&["add-margin", "--pair", &rest, "--side", "long", "--delta", "0.1", "--key", &lk, "--funder", &fk, "--funding", &fund]);
    // Both listings of the remainder cross: close 300 tokens at 10.2.
    let fund = h.funding("f", &f);
    let closed = h.step(&["mutual-close", "--pair", &rest2[0], "--n", "300", "--x", "10.2", "--funder", &fk, "--funding", &fund]);
    let rest3 = closed.iter().find(|p| object_kind(p) == "pair").cloned().expect("remainder");
    assert_eq!(object_size(&rest3), 300_000_000);
    // The two owners close the rest cooperatively: 60/40 of its value.
    let v: Value = serde_json::from_str(&std::fs::read_to_string(&rest3).unwrap()).unwrap();
    let value = v["amount"].as_u64().unwrap();
    let long_pay = format!("{}s", value * 6 / 10);
    let (before_l, before_s) = (h.chain.balance(&l), h.chain.balance(&s));
    h.step(&["coop-close", "--pair", &rest3, "--long-pay", &long_pay, "--fee-from", "short", "--key", &lk, "--key", &sk]);
    assert_eq!(h.chain.balance(&l) - before_l, value * 6 / 10);
    assert!(h.chain.balance(&s) > before_s);
    // The entrant's part idles for 90 days; anyone settles it at its entry price.
    h.chain.advance(77_760_000);
    let fund = h.funding("f", &f);
    h.step(&["idle-settle", "--pair", &part, "--funder", &fk, "--funding", &fund]);
}

#[test]
fn cancel_refund_open_taker_and_close_versus_close() {
    let mut h = H::new("more");
    let market = market_file(&h);
    let (lk, l) = h.key("long");
    let (sk, s) = h.key("short");
    let (fk, f) = h.key("funder");
    let (tk, t) = h.key("taker");
    let (ck, c) = h.key("other");
    for _ in 0..20 {
        h.chain.mint(&f, 4_000 * KAS);
        h.chain.mint(&t, 4_000 * KAS);
    }
    let _ = (&ck, c);

    // Create, then cancel: the escrow comes back to the owner less the fee, and only the owner's key can do it.
    let fund = h.funding("f", &f);
    let o = h.step(&[
        "create-order", "--market", &market, "--side", "long", "--size", "100", "--limit", "10", "--rate", "1", "--expiry", "5000", "--owner", &lk,
        "--funder", &fk, "--funding", &fund,
    ]);
    let err = h.fail(&["cancel", "--order", &o[0], "--key", &fk, "--out-dir", &h.p("nope")]);
    assert!(err.contains("verification failed") || err.contains("input 0"), "{err}");
    let before = h.chain.balance(&l);
    h.step(&["cancel", "--order", &o[0], "--key", &lk]);
    assert!(h.chain.balance(&l) > before);

    // Refund after expiry (anyone pays the fee; the owner gets the whole escrow).
    let fund = h.funding("f", &f);
    let o = h.step(&[
        "create-order", "--market", &market, "--side", "short", "--size", "100", "--limit", "10", "--rate", "1", "--expiry", "5000", "--owner", &sk,
        "--funder", &fk, "--funding", &fund,
    ]);
    let fund = h.funding("f", &f);
    let (ok, _, err) = h.run(&["refund", "--order", &o[0], "--funder", &fk, "--funding", &fund, "--out-dir", &h.p("early"), "--brief"]);
    assert!(ok, "building is fine, the chain would refuse it before expiry: {err}");
    h.chain.advance(5_000);
    h.step(&["refund", "--order", &o[0], "--funder", &fk, "--funding", &fund_after(&h, &f)]);
    assert!(h.chain.balance(&s) > 0);

    // Order x signing taker: a long order of 1,000 tokens meets the taker (key t) as the short.
    let fund = h.funding("f", &f);
    let lo = h.step(&[
        "create-order", "--market", &market, "--side", "long", "--size", "1000", "--limit", "10.5", "--rate", "1", "--min-counter-rate", "1",
        "--min-fill", "100", "--expiry", "1000000000", "--owner", &lk, "--funder", &fk, "--funding", &fund,
    ]);
    let tfund = h.funding("t", &t);
    let opened = h.step(&["open-taker", "--order", &lo[0], "--n", "1000", "--x", "10", "--rate", "1.5", "--funder", &tk, "--funding", &tfund]);
    let p1 = opened.iter().find(|p| object_kind(p) == "pair").cloned().unwrap();

    // A second pair with a deeper range, then close-versus-close: P1 (host, bl 9, bs 11.5) vs P2 (donor, bl 8.5, bs 11.5).
    let fund = h.funding("f", &f);
    let lo2 = h.step(&[
        "create-order", "--market", &market, "--side", "long", "--size", "1000", "--limit", "10.5", "--rate", "1.5", "--min-counter-rate", "1",
        "--min-fill", "100", "--expiry", "1000000000", "--owner", &lk, "--funder", &fk, "--funding", &fund,
    ]);
    let tfund = h.funding("t", &t);
    let opened = h.step(&["open-taker", "--order", &lo2[0], "--n", "1000", "--x", "10", "--rate", "1.5", "--funder", &tk, "--funding", &tfund]);
    let p2 = opened.iter().find(|p| object_kind(p) == "pair").cloned().unwrap();
    let fund = h.funding("f", &f);
    let h1 = h.step(&["amend", "--pair", &p1, "--side", "long", "--price", "10.2", "--key", &lk, "--funder", &fk, "--funding", &fund]);
    let fund = h.funding("f", &f);
    let d1 = h.step(&["amend", "--pair", &p2, "--side", "short", "--price", "10.4", "--key", &tk, "--funder", &fk, "--funding", &fund]);
    let fund = h.funding("f", &f);
    let out = h.step(&["close-vs-close", "--host", &h1[0], "--donor", &d1[0], "--n", "400", "--x", "10.3", "--funder", &fk, "--funding", &fund]);
    assert_eq!(out.iter().filter(|p| object_kind(p) == "pair").count(), 3, "P3, the host remainder and the donor remainder");
}

fn fund_after(h: &H, f: &[u8; 32]) -> String {
    h.funding("f2", f)
}

#[test]
fn refusals_and_safety() {
    let h = H::new("safe");
    let market = market_file(&h);
    let (_k, pk) = h.key("a");
    // Mainnet is refused everywhere with the message.
    let main = kpf_protocol::network::p2pk_address(&pk, kpf_protocol::network::Network::Testnet10).replacen("kaspatest:", "kaspa:", 1);
    for args in [vec!["address", "--pubkey", &main], vec!["address", "--pubkey", "x", "--network", "mainnet"], vec!["keygen", "--network", "mainnet", "--out", "/x"]] {
        let err = h.fail(&args);
        assert!(err.contains("KPF is a testnet-only research prototype"), "{args:?}: {err}");
    }
    // A node URL is explicit, plain ws, and --submit needs one: all refused before anything is sent or even opened.
    let (kf, _) = h.key("fund");
    let err = h.fail(&["utxos", "--key", &kf, "--node", "wss://node.example:17210"]);
    assert!(err.contains("ws://") && err.contains("tunnel"), "{err}");
    let err = h.fail(&["utxos", "--key", &kf]);
    assert!(err.contains("--node"), "{err}");
    let err = h.fail(&[
        "create-order", "--market", &market, "--side", "long", "--size", "10", "--limit", "10", "--rate", "1", "--expiry", "99", "--funder", &kf, "--submit",
    ]);
    assert!(err.contains("no funding"), "{err}");
    // Unknown flags are errors, not ignored.
    let err = h.fail(&["amend", "--pair", "x", "--sid", "long"]);
    assert!(err.contains("unknown option"), "{err}");
    // keygen never prints the secret unless asked, refuses overwrite, and refuses a path inside this repository.
    let kp = h.p("k2.json");
    let out = h.ok(&["keygen", "--out", &kp]);
    let secret = serde_json::from_str::<Value>(&std::fs::read_to_string(&kp).unwrap()).unwrap()["secretKey"].as_str().unwrap().to_string();
    assert!(!out.contains(&secret));
    let out = h.ok(&["keygen", "--out", &h.p("k3.json"), "--show-secret"]);
    assert!(out.contains("secret key"));
    assert!(h.fail(&["keygen", "--out", &kp]).contains("refusing to overwrite"));
    let in_repo = Path::new(env!("CARGO_MANIFEST_DIR")).join("kpf-test-key.json");
    let err = h.fail(&["keygen", "--out", &in_repo.display().to_string()]);
    assert!(err.contains("git working tree"), "{err}");
    assert!(!in_repo.exists());
}

#[test]
fn default_key_location_is_outside_the_repository() {
    let h = H::new("home");
    let home = h.p("home");
    std::fs::create_dir_all(&home).unwrap();
    let o = bin().args(["keygen", "--name", "alice"]).env("USERPROFILE", &home).env("HOME", &home).output().unwrap();
    assert!(o.status.success(), "{}", String::from_utf8_lossy(&o.stderr));
    let expect = Path::new(&home).join(".kpf").join("keys").join("alice.json");
    assert!(expect.exists());
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        assert_eq!(std::fs::metadata(&expect).unwrap().permissions().mode() & 0o777, 0o600);
    }
}

#[test]
fn the_cli_builds_what_the_library_builds() {
    // The same inputs through the binary and through the library give the same transaction id.
    use kpf_protocol::build::*;
    use kpf_protocol::fixtures::*;
    use kpf_protocol::tx::KeyUtxo;
    let h = H::new("same");
    let kf = h.p("fixed.key.json");
    // A TEST-ONLY fixed key (`[24; 32]`), written the way `keygen` writes a file.
    let (sec, pubk) = (secret(24), pubkey(24));
    std::fs::write(
        &kf,
        json!({"format": "kpf-key/1", "network": "testnet-10", "secretKey": kpf_protocol::error::to_hex(&sec), "publicKey": kpf_protocol::error::to_hex(&pubk)}).to_string(),
    )
    .unwrap();
    let op = TransactionOutpoint { transaction_id: kaspa_consensus_core::tx::TransactionId::from_bytes([0x55; 32]), index: 3 };
    let funding = h.p("fund.json");
    std::fs::write(&funding, json!([{"txid": op.transaction_id.to_string(), "index": 3, "amount": 3_000 * KAS, "daa": 7}]).to_string()).unwrap();
    let market = market_file(&h);
    let out = h.p("o");
    h.ok(&[
        "create-order", "--market", &market, "--side", "long", "--size", "2000", "--limit", "10.5", "--rate", "1", "--min-counter-rate", "1.5",
        "--min-fill", "100", "--tip", "0.01", "--expiry", "1000000000", "--owner", &kpf_protocol::error::to_hex(&pubkey(21)), "--funder", &kf, "--funding", &funding,
        "--out-dir", &out, "--brief",
    ]);
    let txfile = std::fs::read_dir(&out).unwrap().map(|e| e.unwrap().path()).find(|p| p.to_string_lossy().ends_with("-tx.json")).unwrap();
    let doc: Value = serde_json::from_str(&std::fs::read_to_string(txfile).unwrap()).unwrap();
    let f = Funding { utxos: vec![KeyUtxo { outpoint: op, amount: 3_000 * KAS, daa: 7, key: pubk }], change_key: pubk };
    let b = create_order(&long_order(pubkey(21)), &f, &Opts::default()).unwrap();
    let s = b.sign(&keyset(&[24])).unwrap();
    assert_eq!(doc["txid"].as_str().unwrap(), s.txid().to_string());
    assert_eq!(doc["fee"].as_u64().unwrap(), s.fee);
}

/// The exact sequence of `docs/TESTNET.md`, with its numbers: a market with a 3,000 DAA idle timeout, tens of KAS.
#[test]
fn runbook_scenario() {
    let mut h = H::new("runbook");
    let (ok, mk, _) = h.run(&["market", "--idle-daa", "3000", "--carrier", "0.2"]);
    assert!(ok);
    let market = h.p("market.json");
    std::fs::write(&market, mk).unwrap();
    let (alice, a) = h.key("alice"); // funder, long
    let (bob, b) = h.key("bob"); // short
    let (carol, c) = h.key("carol"); // second short (entrant)
    let start = 150 * KAS;
    h.chain.mint(&a, start);
    let _ = (&bob, &carol, b, c);
    let fund = |h: &H| h.funding("a", &a);

    let lo = h.step(&[
        "create-order", "--market", &market, "--side", "long", "--size", "20", "--limit", "10.5", "--rate", "1", "--min-counter-rate", "1.5", "--min-fill", "1",
        "--tip", "0.01", "--expiry", "100000", "--owner", &alice, "--funder", &alice, "--funding", &fund(&h),
    ]);
    let so = h.step(&[
        "create-order", "--market", &market, "--side", "short", "--size", "10", "--limit", "9.5", "--rate", "2", "--min-counter-rate", "0.5", "--min-fill", "1",
        "--tip", "0.01", "--expiry", "100000", "--owner", &bob, "--funder", &alice, "--funding", &fund(&h),
    ]);
    let so2 = h.step(&[
        "create-order", "--market", &market, "--side", "short", "--size", "10", "--limit", "9", "--rate", "2.2", "--min-counter-rate", "0.5", "--min-fill", "1",
        "--tip", "0.01", "--expiry", "100000", "--owner", &carol, "--funder", &alice, "--funding", &fund(&h),
    ]);
    let opened = h.step(&["open", "--long", &lo[0], "--short", &so[0], "--n", "10", "--x", "10", "--funder", &alice, "--funding", &fund(&h)]);
    let pair = opened.iter().find(|p| object_kind(p) == "pair").cloned().unwrap();
    let l1 = h.step(&["amend", "--pair", &pair, "--side", "long", "--price", "10", "--key", &alice, "--funder", &alice, "--funding", &fund(&h)]);
    let l2 = h.step(&["amend", "--pair", &l1[0], "--side", "short", "--price", "10.5", "--key", &bob, "--funder", &alice, "--funding", &fund(&h)]);
    let moved = h.step(&["transfer", "--pair", &l2[0], "--side", "short", "--n", "4", "--x", "10.2", "--entrant-order", &so2[0], "--funder", &alice, "--funding", &fund(&h)]);
    let part = moved.iter().find(|p| object_size(p) == 4_000_000).cloned().unwrap();
    let rest = moved.iter().find(|p| object_size(p) == 6_000_000).cloned().unwrap();
    let rest2 = h.step(&["add-margin", "--pair", &rest, "--side", "long", "--delta", "0.1", "--key", &alice, "--funder", &alice, "--funding", &fund(&h)]);
    let closed = h.step(&["mutual-close", "--pair", &rest2[0], "--n", "3", "--x", "10.2", "--funder", &alice, "--funding", &fund(&h)]);
    let rest3 = closed.iter().find(|p| object_kind(p) == "pair").cloned().unwrap();
    let v: Value = serde_json::from_str(&std::fs::read_to_string(&rest3).unwrap()).unwrap();
    let half = format!("{}s", v["amount"].as_u64().unwrap() / 2);
    h.step(&["coop-close", "--pair", &rest3, "--long-pay", &half, "--fee-from", "short", "--key", &alice, "--key", &bob]);
    // The entrant's part idles: settle it after the 3,000 DAA of this market.
    h.chain.advance(3_000);
    h.step(&["idle-settle", "--pair", &part, "--funder", &alice, "--funding", &fund(&h)]);
    // Spare order: cancel the entrant order's leftover (6 tokens): carol's key.
    let leftover = h.p("out7/").to_string();
    let _ = leftover;
    let spent = start - h.chain.balance(&a);
    println!("funder balance change over the whole scenario: -{} sompi", spent);
}
